using Android.App;
using Android.Graphics;
using Android.OS;
using Android.Views;
using Android.Webkit;
using Android.Widget;

namespace PyApp
{
    /// <summary>
    /// Aurora Notes — generated by AppForge (com.appforge.aurora).
    /// </summary>
    [Activity(Label = "@string/app_name", MainLauncher = true, Exported = true)]
    public class MainActivity : Activity
    {
        private const string HomeUrl = "https://lysagaming.com";
        private const string PrimaryColor = "#6366F1";
        private const string SurfaceColor = "#0B1220";
        private const bool AllowZoom = true;

        private WebView _web;

        protected override void OnCreate(Bundle savedInstanceState)
        {
            base.OnCreate(savedInstanceState);

            if (Window != null)
            {
                Window.SetStatusBarColor(Color.ParseColor(PrimaryColor));
            }

            var root = new LinearLayout(this) { Orientation = Orientation.Vertical };
            root.SetBackgroundColor(Color.ParseColor(SurfaceColor));

            _web = new WebView(this);
            WebSettings settings = _web.Settings;
            settings.JavaScriptEnabled = true;
            settings.DomStorageEnabled = true;
            settings.BuiltInZoomControls = AllowZoom;
            settings.DisplayZoomControls = false;
            settings.LoadWithOverviewMode = true;
            settings.UseWideViewPort = true;

            _web.SetWebViewClient(new WebViewClient());
            _web.SetWebChromeClient(new WebChromeClient());
            _web.LoadUrl(HomeUrl);

            root.AddView(_web, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MatchParent,
                ViewGroup.LayoutParams.MatchParent));

            SetContentView(root);
        }

        public override void OnBackPressed()
        {
            if (_web != null && _web.CanGoBack())
            {
                _web.GoBack();
                return;
            }
            base.OnBackPressed();
        }

        protected override void OnDestroy()
        {
            if (_web != null)
            {
                _web.Destroy();
                _web = null;
            }
            base.OnDestroy();
        }
    }
}
